-- Economics Gen2 Practice: focused presentation/content patch. Original answered questions remain addressable.
-- Safe: one existing-word case correction, Russian decimal display correction, one append-only question replacement.
-- No changes to scores, answer keys, legacy question rows (except cosmetic text), tours, certificates or users.
BEGIN;
SET LOCAL lock_timeout = '6s';
SET LOCAL statement_timeout = '20s';
DO $eco$
DECLARE
  v_q1 bigint; v_q2 bigint; v_old bigint; v_new bigint; v_pool bigint; v_order integer; v_num integer;
BEGIN
  SELECT id INTO STRICT v_q1 FROM public.questions WHERE subject_id=7 AND book_ref='EC9708:G2:EC9708-G2-T7-P-046';
  SELECT id INTO STRICT v_q2 FROM public.questions WHERE subject_id=7 AND book_ref='EC9708:G2:EC9708-G2-T7-P-058';
  SELECT id INTO STRICT v_old FROM public.questions WHERE subject_id=7 AND book_ref='EC9708:G2:EC9708-G2-T7-P-048';
  IF (SELECT correct_answer FROM public.questions WHERE id=v_q1) <> 'D' OR (SELECT correct_answer FROM public.questions WHERE id=v_q2) <> 'A' OR (SELECT correct_answer FROM public.questions WHERE id=v_old) <> 'C' THEN RAISE EXCEPTION 'economics_practice_key_drift'; END IF;
  IF (SELECT question_text_ru FROM public.questions WHERE id=v_q1) NOT LIKE '%ВЕС партнёра A%' AND (SELECT question_text_ru FROM public.questions WHERE id=v_q1) NOT LIKE '%вес партнёра A%' THEN RAISE EXCEPTION 'economics_p046_stem_drift'; END IF;
  UPDATE public.questions SET question_text_ru=replace(question_text_ru,'ВЕС партнёра A','вес партнёра A') WHERE id=v_q1 AND question_text_ru LIKE '%ВЕС партнёра A%';
  IF (SELECT options_text_ru::jsonb FROM public.questions WHERE id=v_q2) NOT IN (jsonb_build_array('58.9%','63.0%','56.0%','52.3%'),jsonb_build_array('58,9%','63,0%','56,0%','52,3%')) THEN RAISE EXCEPTION 'economics_p058_options_drift'; END IF;
  UPDATE public.questions SET options_text_ru=jsonb_build_array('58,9%','63,0%','56,0%','52,3%')::text, explanation_ru=replace(replace(replace(replace(explanation_ru,'58.9%','58,9%'),'63.0%','63,0%'),'56.0%','56,0%'),'52.3%','52,3%') WHERE id=v_q2;
  SELECT count(*) INTO v_num FROM public.question_answer_diagnostics WHERE question_id=v_q2 AND answer_kind='mcq_option';
  IF v_num<>4 THEN RAISE EXCEPTION 'economics_p058_feedback_count_drift: %',v_num; END IF;
  UPDATE public.question_answer_diagnostics SET feedback_ru=replace(replace(replace(replace(feedback_ru,'58.9%','58,9%'),'63.0%','63,0%'),'56.0%','56,0%'),'52.3%','52,3%') WHERE question_id=v_q2 AND answer_kind='mcq_option';
  SELECT id INTO v_new FROM public.questions WHERE subject_id=7 AND book_ref='EC9708:G2:EC9708-G2-T7-P-048-V2';
  IF v_new IS NULL THEN
    SELECT pp.pool_id,pp.order_no INTO STRICT v_pool,v_order FROM public.practice_pool_questions pp JOIN public.practice_pools p ON p.id=pp.pool_id WHERE pp.question_id=v_old AND pp.is_active=true AND p.subject_id=7 AND p.tour_no=7;
    INSERT INTO public.questions (subject_id,topic,subtopic,difficulty,qtype,question_text,options_text,correct_answer,explanation,image_url,is_active,question_text_ru,question_text_uz,question_text_en,options_text_ru,options_text_uz,options_text_en,explanation_ru,explanation_uz,explanation_en,book_ref,time_limit_sec,quality_flag,quality_status)
    SELECT src.subject_id,src.topic,src.subtopic,'medium','mcq','A foreign food-processing company trains local workers, imports modern machinery and buys inputs from local suppliers. Later, some trained workers join domestic firms. Which possible long-run effect on the host economy is best supported?','["The imported machinery is recorded as a host-country export, improving its current account.","Workers changing employer increases the stock of physical capital even without acquiring new assets.","Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.","Purchases from domestic suppliers are counted as exports and directly improve the trade balance."]','C','Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.
Why: Training and worker mobility can spread skills, while supplier relationships can transfer methods. These are possible positive knowledge spillovers, not guaranteed benefits.',NULL,true,'Иностранная компания открывает пищевой завод, обучает местных работников, импортирует современное оборудование и закупает сырьё у местных поставщиков. Позже часть обученных сотрудников переходит в отечественные фирмы. Какой возможный долгосрочный эффект для экономики принимающей страны наиболее обоснован?','Xorijiy kompaniya oziq-ovqatni qayta ishlash zavodini ochadi, mahalliy ishchilarni o‘qitadi, zamonaviy uskunalar import qiladi va mahalliy yetkazib beruvchilardan xomashyo sotib oladi. Keyinroq o‘qitilgan ishchilarning bir qismi mahalliy firmalarga o‘tadi. Qabul qiluvchi mamlakat iqtisodiyoti uchun qaysi uzoq muddatli taʼsir eng asosli?','A foreign food-processing company trains local workers, imports modern machinery and buys inputs from local suppliers. Later, some trained workers join domestic firms. Which possible long-run effect on the host economy is best supported?','["Импортированное оборудование учитывается как экспорт принимающей страны и улучшает её текущий счёт.","Переход обученных работников увеличивает запас физического капитала даже без приобретения новых активов.","Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.","Закупки у местных поставщиков учитываются как экспорт и напрямую улучшают торговый баланс."]','["Import qilingan uskunalar qabul qiluvchi mamlakat eksporti sifatida hisobga olinib, uning joriy hisobini yaxshilaydi.","O‘qitilgan ishchilarning boshqa firmaga o‘tishi yangi aktivlar olinmasa ham jismoniy kapital zaxirasini oshiradi.","Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.","Mahalliy yetkazib beruvchilardan xaridlar eksport sifatida hisoblanib, savdo balansini bevosita yaxshilaydi."]','["The imported machinery is recorded as a host-country export, improving its current account.","Workers changing employer increases the stock of physical capital even without acquiring new assets.","Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.","Purchases from domestic suppliers are counted as exports and directly improve the trade balance."]','Правильный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.
Почему: Обучение и переход работников распространяют навыки, а связи с поставщиками могут передавать новые методы. Это возможные положительные эффекты распространения знаний, но не гарантированный результат.','To‘g‘ri javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.
Sabab: Ishchilarni o‘qitish va ularning boshqa firmaga o‘tishi ko‘nikmalarni tarqatadi, yetkazib beruvchilar bilan aloqalar esa yangi usullarni yoyishi mumkin. Bu bilimlar tarqalishining ehtimoliy ijobiy taʼsiri, kafolatlangan natija emas.','Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.
Why: Training and worker mobility can spread skills, while supplier relationships can transfer methods. These are possible positive knowledge spillovers, not guaranteed benefits.','EC9708:G2:EC9708-G2-T7-P-048-V2',120,src.quality_flag,'published' FROM public.questions src WHERE src.id=v_old RETURNING id INTO v_new;
    UPDATE public.practice_pool_questions SET is_active=false WHERE pool_id=v_pool AND question_id=v_old AND is_active=true;
    GET DIAGNOSTICS v_num=ROW_COUNT; IF v_num<>1 THEN RAISE EXCEPTION 'economics_p048_old_pool_link_drift'; END IF;
    INSERT INTO public.practice_pool_questions (pool_id,question_id,order_no,is_active) VALUES (v_pool,v_new,v_order,true);
    INSERT INTO public.question_version_links(old_question_id,new_question_id,link_type,reason) VALUES (v_old,v_new,'replacement','Economics Gen2 Tour 7 Practice: replace obvious categorical distractors with concept-based alternatives; preserve saved answers and correct key C');
    INSERT INTO public.question_answer_diagnostics(question_id,answer_kind,answer_key,answer_value,is_correct,mistake_type,weak_skill,feedback_ru,feedback_uz,feedback_en,next_action_ru,next_action_uz,next_action_en,rule_json,quality_status)
    VALUES
      (v_new,'mcq_option','A',NULL,false,'current_account_import_export','FDI knowledge spillovers','Выбранный ответ: Импортированное оборудование учитывается как экспорт принимающей страны и улучшает её текущий счёт.
Объяснение: Ввоз оборудования — импорт принимающей страны, а не её экспорт. Сам по себе он не улучшает сальдо текущего счёта.
Правильный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.','Tanlangan javob: Import qilingan uskunalar qabul qiluvchi mamlakat eksporti sifatida hisobga olinib, uning joriy hisobini yaxshilaydi.
Izoh: Uskunani olib kirish qabul qiluvchi mamlakat uchun importdir, eksport emas. Bu xaridning o‘zi joriy hisob saldosini yaxshilamaydi.
To‘g‘ri javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.','Selected answer: The imported machinery is recorded as a host-country export, improving its current account.
Reason: Imported machinery is an import, not an export, for the host economy. Its purchase does not by itself improve the current account.
Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.','Сравните внешнеторговые операции с передачей навыков и человеческим капиталом.','Tashqi savdo operatsiyalari, inson kapitali va ko‘nikmalar tarqalishini farqlang.','Distinguish cross-border transactions from human capital and knowledge spillovers.',jsonb_build_object('diagnostic_code','EC9708_G2_T7P048_V2_A'),'published'),
      (v_new,'mcq_option','B',NULL,false,'human_vs_physical_capital','FDI knowledge spillovers','Выбранный ответ: Переход обученных работников увеличивает запас физического капитала даже без приобретения новых активов.
Объяснение: Приобретённые работниками навыки — человеческий капитал. Смена работодателя сама по себе не создаёт дополнительного оборудования или зданий.
Правильный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.','Tanlangan javob: O‘qitilgan ishchilarning boshqa firmaga o‘tishi yangi aktivlar olinmasa ham jismoniy kapital zaxirasini oshiradi.
Izoh: Ishchilarning yangi ko‘nikmalari inson kapitalidir. Ish joyini o‘zgartirish o‘z-o‘zidan qo‘shimcha uskuna yoki binolarni yaratmaydi.
To‘g‘ri javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.','Selected answer: Workers changing employer increases the stock of physical capital even without acquiring new assets.
Reason: Employees'' acquired skills are human capital. Moving employer does not itself create additional physical machinery or buildings.
Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.','Сравните внешнеторговые операции с передачей навыков и человеческим капиталом.','Tashqi savdo operatsiyalari, inson kapitali va ko‘nikmalar tarqalishini farqlang.','Distinguish cross-border transactions from human capital and knowledge spillovers.',jsonb_build_object('diagnostic_code','EC9708_G2_T7P048_V2_B'),'published'),
      (v_new,'mcq_option','C',NULL,true,NULL,'FDI knowledge spillovers','Выбранный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.
Объяснение: Обучение, переход работников и связи с поставщиками могут распространять знания и повышать производительность отечественных фирм.
Правильный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.','Tanlangan javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.
Izoh: O‘qitish, xodimlarning boshqa firmaga o‘tishi va yetkazib beruvchilar bilan aloqalar bilimlar tarqalishiga hamda mahalliy firmalar unumdorligi oshishiga yordam berishi mumkin.
To‘g‘ri javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.','Selected answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.
Reason: Training, worker mobility and supplier links can generate positive knowledge spillovers, potentially raising productivity in domestic firms.
Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.',NULL,NULL,NULL,jsonb_build_object('diagnostic_code','EC9708_G2_T7P048_V2_C'),'published'),
      (v_new,'mcq_option','D',NULL,false,'domestic_purchase_vs_export','FDI knowledge spillovers','Выбранный ответ: Закупки у местных поставщиков учитываются как экспорт и напрямую улучшают торговый баланс.
Объяснение: Сделка между местными компаниями не является трансграничным экспортом и сама по себе не увеличивает экспортную выручку.
Правильный ответ: Навыки и методы производства могут распространиться на местные фирмы, повышая производительность за пределами иностранного завода.','Tanlangan javob: Mahalliy yetkazib beruvchilardan xaridlar eksport sifatida hisoblanib, savdo balansini bevosita yaxshilaydi.
Izoh: Ikki mahalliy firma o‘rtasidagi oldi-sotdi transchegaraviy eksport emas va eksport tushumini o‘z-o‘zidan oshirmaydi.
To‘g‘ri javob: Ko‘nikmalar va ishlab chiqarish usullari mahalliy firmalarga tarqalib, xorijiy zavoddan tashqarida ham unumdorlikni oshirishi mumkin.','Selected answer: Purchases from domestic suppliers are counted as exports and directly improve the trade balance.
Reason: A transaction between two domestic firms is not a cross-border export; it does not itself increase export receipts.
Correct answer: Production skills and methods can spread to domestic firms, raising productivity beyond the foreign-owned plant.','Сравните внешнеторговые операции с передачей навыков и человеческим капиталом.','Tashqi savdo operatsiyalari, inson kapitali va ko‘nikmalar tarqalishini farqlang.','Distinguish cross-border transactions from human capital and knowledge spillovers.',jsonb_build_object('diagnostic_code','EC9708_G2_T7P048_V2_D'),'published');
  ELSE
    SELECT count(*) INTO v_num FROM public.practice_pool_questions WHERE question_id=v_new AND is_active=true;
    IF v_num<>1 THEN RAISE EXCEPTION 'economics_p048_v2_existing_but_not_live'; END IF;
  END IF;
  SELECT count(*) INTO v_num FROM public.practice_pool_questions x JOIN public.practice_pools p ON p.id=x.pool_id WHERE p.subject_id=7 AND p.tour_no=7 AND x.is_active=true;
  IF v_num<>70 THEN RAISE EXCEPTION 'economics_tour7_practice_membership_changed: %',v_num; END IF;
  IF (SELECT count(*) FROM public.question_answer_diagnostics WHERE question_id=v_new AND answer_kind='mcq_option' AND quality_status='published')<>4 THEN RAISE EXCEPTION 'economics_p048_v2_feedback_incomplete'; END IF;
  IF (SELECT correct_answer FROM public.questions WHERE id=v_new) <> 'C' THEN RAISE EXCEPTION 'economics_p048_v2_key_changed'; END IF;
END $eco$;
COMMIT;
